import prismaMock from '../prisma-mock';
import {
  deleteComment,
  favoriteArticle,
  unfavoriteArticle,
  updateComment,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });
  });

  describe('updateComment', () => {
    const slug = 'How-to-train-your-dragon';
    const commentId = 123;
    const authorId = 456;

    const mockedUpdatedComment = {
      id: commentId,
      createdAt: new Date('2026-10-01T10:00:00Z'),
      updatedAt: new Date('2026-10-02T10:00:00Z'),
      body: 'Edited body',
      authorId,
      articleId: 789,
      author: {
        username: 'RealWorld',
        bio: null,
        image: null,
        followedBy: [],
      },
    };

    test('should update the body of the comment for its author', async () => {
      // Given
      const body = 'Edited body';

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ id: commentId });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // Then
      const result = await updateComment(body, slug, commentId, authorId);

      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: {
            id: commentId,
            article: { slug },
            author: { id: authorId },
          },
        }),
      );
      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({
            body,
            updatedAt: expect.any(Date),
          }),
        }),
      );
      expect(result).toEqual({
        id: commentId,
        createdAt: mockedUpdatedComment.createdAt,
        updatedAt: mockedUpdatedComment.updatedAt,
        body: 'Edited body',
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          following: false,
        },
      });
    });

    test('should refuse the edit when the user is not the author', async () => {
      // Given
      const otherUserId = 999;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(
        updateComment('Edited body', slug, commentId, otherUserId),
      ).rejects.toMatchObject({ errorCode: 404 });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should refuse the edit when the body is empty', async () => {
      // Given
      const body = '';

      // Then
      await expect(updateComment(body, slug, commentId, authorId)).rejects.toMatchObject({
        errorCode: 422,
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
